// Combine messages and notifications
const messages = $items('Get New Messages', 0, $items('Get New Messages').length);
const notifications = $items('Get New Notifications', 0, $items('Get New Notifications').length);

const items = [];
for (let i = 0; i < messages.length; i++) {
  const m = messages[i].json;
  items.push({
    type: 'whatsapp',
    source: m.source,
    chat_id: m.chat_id,
    chat_name: m.chat_name,
    is_group: m.is_group,
    sender: m.sender_name || m.sender_id,
    content: m.content,
    timestamp: m.timestamp,
    mentioned_me: m.mentioned_me,
    id: m.id
  });
}
for (let i = 0; i < notifications.length; i++) {
  const n = notifications[i].json;
  items.push({
    type: 'notification',
    app_package: n.app_package,
    app_name: n.app_name,
    title: n.title,
    content: n.content,
    timestamp: n.post_time,
    id: n.id
  });
}

items.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

return {items: items, count: items.length};

// Simple heuristic for context priority (can be enhanced with LLM)
const items = $json.items;
const config = $items('Get Config')[0]?.json.value || {debounce_minutes_nonurgent: 10, priority_threshold: 60};
const contextState = $items('Get Context State')[0]?.json || {};

const urgentKeywords = ['asap', 'urgent', 'emergency', 'deadline', 'due', 'overdue', 'pay now', 'meeting now', 'immediately'];
const questionKeywords = ['can you', 'could you', 'will you', 'are you', 'do you', '?'];
const timeKeywords = ['tomorrow', 'today', 'tonight', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday', 'am', 'pm', 'by '];

let score = 0;
let reasons = [];

const now = new Date();
const lastSummary = new Date(contextState.last_summary_at || '1970-01-01');
const minutesSince = (now - lastSummary) / (1000 * 60);

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const text = (item.content || item.title || '').toLowerCase();

  for (let k = 0; k < urgentKeywords.length; k++) {
    if (text.includes(urgentKeywords[k])) {
      score += 30;
      reasons.push('urgent_keyword');
      break;
    }
  }

  if (item.mentioned_me) {
    score += 25;
    reasons.push('mention');
  }

  for (let k = 0; k < questionKeywords.length; k++) {
    if (text.includes(questionKeywords[k]) || text.endsWith('?')) {
      score += 15;
      reasons.push('question');
      break;
    }
  }

  for (let k = 0; k < timeKeywords.length; k++) {
    if (text.includes(timeKeywords[k])) {
      score += 20;
      reasons.push('time_entity');
      break;
    }
  }
}

// Burst detection
if (items.length >= 5) {
  score += 20;
  reasons.push('burst');
}

// Boost if it's been a while
if (minutesSince > 60) {
  score += 10;
}

const uniqueReasons = [...new Set(reasons)];
const threshold = config.priority_threshold || 60;
const shouldSummarize = score >= threshold || minutesSince > 180;

return {
  items: items,
  score: score,
  reasons: uniqueReasons,
  shouldSummarize: shouldSummarize,
  minutesSinceLastSummary: Math.round(minutesSince),
  config: config
};

// Parse LLM response
const response = $json.message?.content || $json.text || $json.choices?.[0]?.message?.content || '';
let parsed;
try {
  // Remove markdown code blocks if present
  const cleaned = response.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    summary_text: response,
    summary_json: {
      overview: response.substring(0, 100),
      urgent: [],
      deadlines: [],
      action_items: [],
      fyi: []
    },
    trigger_reason: $items('Calculate Priority')[0].json.reasons.join(',')
  };
}

const items = $items('Calculate Priority')[0].json.items;
const whatsappCount = items.filter(i => i.type === 'whatsapp').length;
const notifCount = items.filter(i => i.type === 'notification').length;

return {
  ...parsed,
  message_count: whatsappCount,
  notification_count: notifCount,
  time_range_start: items[0]?.timestamp,
  time_range_end: items[items.length-1]?.timestamp
};
